CREATE TABLE organizations(id uuid PRIMARY KEY,name text NOT NULL);
CREATE TABLE restaurants(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,currency text NOT NULL DEFAULT 'MXN',timezone text NOT NULL DEFAULT 'America/Mexico_City',cutoff integer NOT NULL DEFAULT 240 CHECK(cutoff BETWEEN 0 AND 1439),opening_days integer[] NOT NULL DEFAULT '{1,2,3,4,5,6,7}');
CREATE TABLE employees(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,name text NOT NULL,login text NOT NULL,secret_hash text NOT NULL,role text NOT NULL CHECK(role IN ('owner','manager','cashier','server','kitchen')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,login));
CREATE TABLE devices(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,name text NOT NULL,token_hash text NOT NULL,active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,id));
CREATE TABLE sessions(tenant_id uuid NOT NULL,id uuid NOT NULL,employee_id uuid NOT NULL,device_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,csrf text NOT NULL,expires_at timestamptz NOT NULL,offline_until timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,employee_id) REFERENCES employees(tenant_id,id),FOREIGN KEY(tenant_id,device_id) REFERENCES devices(tenant_id,id));
CREATE TABLE catalog(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,data jsonb NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE dining_tables(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,name text NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE order_numbers(tenant_id uuid NOT NULL REFERENCES restaurants(id),business_date date NOT NULL,value integer NOT NULL,PRIMARY KEY(tenant_id,business_date));
CREATE TABLE orders(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,number integer NOT NULL,business_date date NOT NULL,employee_id uuid NOT NULL,table_id uuid,version integer NOT NULL DEFAULT 1,mode text NOT NULL,name text NOT NULL,note text NOT NULL,channel text NOT NULL,state text NOT NULL DEFAULT 'active',total integer NOT NULL CHECK(total>=0),discount integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,business_date,number),FOREIGN KEY(tenant_id,employee_id) REFERENCES employees(tenant_id,id),FOREIGN KEY(tenant_id,table_id) REFERENCES dining_tables(tenant_id,id));
CREATE TABLE order_lines(tenant_id uuid NOT NULL,id uuid NOT NULL,order_id uuid NOT NULL,product_id uuid NOT NULL,round integer NOT NULL,data jsonb NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES catalog(tenant_id,id));
CREATE TABLE rounds(tenant_id uuid NOT NULL,id uuid NOT NULL,order_id uuid NOT NULL,number integer NOT NULL,station text NOT NULL,state text NOT NULL DEFAULT 'active',seen_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,order_id,number,station),FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id));
CREATE TABLE cash_sessions(tenant_id uuid NOT NULL,id uuid NOT NULL,device_id uuid NOT NULL,employee_id uuid NOT NULL,opening integer NOT NULL CHECK(opening>=0),counted integer,expected integer,reason text,opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,device_id) REFERENCES devices(tenant_id,id),FOREIGN KEY(tenant_id,employee_id) REFERENCES employees(tenant_id,id));
CREATE UNIQUE INDEX one_open_drawer ON cash_sessions(tenant_id,device_id) WHERE closed_at IS NULL;
CREATE TABLE tenders(tenant_id uuid NOT NULL,id uuid NOT NULL,order_id uuid NOT NULL,session_id uuid,method text NOT NULL CHECK(method IN ('cash','external')),amount integer NOT NULL CHECK(amount>0),tip integer NOT NULL DEFAULT 0 CHECK(tip>=0),received integer NOT NULL,external_reference text,group_id uuid,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id),FOREIGN KEY(tenant_id,session_id) REFERENCES cash_sessions(tenant_id,id));
CREATE TABLE refunds(tenant_id uuid NOT NULL,id uuid NOT NULL,tender_id uuid NOT NULL,session_id uuid,amount integer NOT NULL CHECK(amount>0),reason text NOT NULL,disposition text NOT NULL CHECK(disposition IN ('discard','no_stock_return')),actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,tender_id) REFERENCES tenders(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES employees(tenant_id,id),FOREIGN KEY(tenant_id,session_id) REFERENCES cash_sessions(tenant_id,id));
CREATE TABLE cash_movements(tenant_id uuid NOT NULL,id uuid NOT NULL,session_id uuid NOT NULL,amount integer NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,session_id) REFERENCES cash_sessions(tenant_id,id));
CREATE TABLE stock_items(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,name text NOT NULL,unit text NOT NULL,kind text NOT NULL CHECK(kind IN ('raw','prepared')),threshold numeric(18,6) NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,id));
CREATE TABLE stock_movements(tenant_id uuid NOT NULL,id uuid NOT NULL,stock_id uuid NOT NULL,quantity numeric(18,6) NOT NULL,cause text NOT NULL,cause_id text NOT NULL,reason text NOT NULL,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,stock_id,cause,cause_id),FOREIGN KEY(tenant_id,stock_id) REFERENCES stock_items(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES employees(tenant_id,id));
CREATE TABLE jobs(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,kind text NOT NULL,dedupe_key text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,next_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,error_code text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,kind,dedupe_key));
CREATE TABLE audit(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,actor_id uuid NOT NULL,operation text NOT NULL,entity_id text NOT NULL,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES employees(tenant_id,id));
CREATE TABLE operations(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,kind text NOT NULL,hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE import_batches(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,source text NOT NULL,file_hash text NOT NULL,report jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,source,file_hash));
CREATE TABLE source_mappings(tenant_id uuid NOT NULL,source_system text NOT NULL,source_tenant_id text NOT NULL,entity_type text NOT NULL,legacy_id text NOT NULL,target_id uuid NOT NULL,import_batch_id uuid NOT NULL,PRIMARY KEY(tenant_id,source_system,source_tenant_id,entity_type,legacy_id),FOREIGN KEY(tenant_id,import_batch_id) REFERENCES import_batches(tenant_id,id));
CREATE TABLE expenses(tenant_id uuid NOT NULL REFERENCES restaurants(id),id uuid NOT NULL,amount integer NOT NULL CHECK(amount>0),kind text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
DO $$ DECLARE t text; BEGIN
FOREACH t IN ARRAY ARRAY['employees','devices','sessions','catalog','dining_tables','order_numbers','orders','order_lines','rounds','cash_sessions','tenders','refunds','cash_movements','stock_items','stock_movements','jobs','audit','operations','import_batches','source_mappings','expenses'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
EXECUTE format('CREATE POLICY tenant_scope ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t);
END LOOP;
END $$;
ALTER TABLE restaurants ENABLE ROW LEVEL SECURITY;
ALTER TABLE restaurants FORCE ROW LEVEL SECURITY;
CREATE POLICY restaurant_scope ON restaurants USING(id=nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(id=nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY organization_scope ON organizations USING(id IN (SELECT organization_id FROM restaurants));
